def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    bars=[]
    for r in range(h):
        c=0
        while c<w:
            if g[r][c]!=bg:
                c0=c
                while c<w and g[r][c]==g[r][c0]: c+=1
                if c-c0>=2: bars.append((r,c0,c-1,g[r][c0]))
            else: c+=1
    bars.sort()
    top,bot=bars[0],bars[-1]
    X=top[3]
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (bg,X)]
    Y=g[marks[0][0]][marks[0][1]]
    out=[row[:] for row in g]
    for r,c in marks: out[r][c]=4
    def barcell(rr,cc):
        return (rr==top[0] and top[1]<=cc<=top[2]) or (rr==bot[0] and bot[1]<=cc<=bot[2])
    for r,c in marks:
        if top[1]<=c<=top[2]: bar,other=top,bot
        elif bot[1]<=c<=bot[2]: bar,other=bot,top
        else: continue
        lo,hi=min(bar[0],r),max(bar[0],r)
        for rr in range(lo+1,hi):
            if not barcell(rr,c): out[rr][c]=Y
        cm=c+(other[1]-bar[1])
        if 0<=cm<w:
            lo2,hi2=min(top[0],bot[0]),max(top[0],bot[0])
            for rr in range(lo2,hi2+1):
                if not barcell(rr,cm): out[rr][cm]=Y
    return out

